using System;using System.Linq;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 public sealed class CostStrip:MonoBehaviour {
  public void Bind(GameRuntime game,CraftQuote quote){WorkshopUIFactory.Clear(transform);var s=game.State;int count=0;void Add(Sprite art,ScientificNumber have,ScientificNumber need,string suffix=""){if(need.IsZero)return;count++;var chip=WorkshopUIFactory.Node("CostChip",transform,typeof(Image));GameTheme.SurfaceOn(chip.GetComponent<Image>(),GameTheme.Background);var image=WorkshopUIFactory.Node("CostIcon",chip.transform,typeof(Image)).GetComponent<Image>();image.sprite=art;image.preserveAspect=true;image.raycastTarget=false;image.rectTransform.anchorMin=image.rectTransform.anchorMax=new Vector2(0,.5f);image.rectTransform.pivot=new Vector2(0,.5f);image.rectTransform.sizeDelta=new Vector2(24,24);image.rectTransform.anchoredPosition=new Vector2(5,0);var text=WorkshopUIFactory.Label("HaveRequired",chip.transform,NumberFormatting.Format(have,s.Settings.numberFormat)+" / "+NumberFormatting.Format(need,s.Settings.numberFormat)+suffix,12);DestroyImmediate(text.GetComponent<LayoutElement>());WorkshopUIFactory.Fill(text.rectTransform);text.rectTransform.offsetMin=new Vector2(34,0);text.rectTransform.offsetMax=new Vector2(-5,0);text.resizeTextForBestFit=true;text.resizeTextMinSize=10;text.resizeTextMaxSize=12;text.color=have.CompareTo(need)>=0?GameTheme.Enough:GameTheme.Missing;}
   if(quote.Components!=null)for(int i=0;i<quote.Components.Length;i++)Add(game.WorkshopPrefab.ComponentSprites[i],ScientificNumber.From(s.Workshop.components[i]),ScientificNumber.From(quote.Components[i]));Add(game.GetComponent<MobileShell>()?.ResourceIcons[1],s.Data,ScientificNumber.From(quote.Data));if(quote.Modules!=null)for(int i=0;i<quote.Modules.Length;i++)Add(null,ScientificNumber.From(s.Workshop.modules[i]),ScientificNumber.From(quote.Modules[i])," M"+(i+1));var layout=GetComponent<GridLayoutGroup>()??gameObject.AddComponent<GridLayoutGroup>();layout.constraint=GridLayoutGroup.Constraint.FixedColumnCount;layout.constraintCount=2;layout.spacing=new Vector2(4,4);var size=GetComponent<LayoutElement>()??gameObject.AddComponent<LayoutElement>();size.minHeight=size.preferredHeight=Math.Max(1,(count+1)/2)*36;Resize();}
  void OnRectTransformDimensionsChange()=>Resize();void Resize(){var layout=GetComponent<GridLayoutGroup>();if(layout!=null)layout.cellSize=new Vector2(Math.Max(1,(((RectTransform)transform).rect.width-4)/2),32);}
 }
}
